argsPayload:
{
  "command": "git status --porcelain=v2 --branch --untracked-files=all && printf '\\nHEAD=' && git rev-parse HEAD && printf '\\nBRANCH=' && (git symbolic-ref --quiet --short HEAD || echo DETACHED) && printf '\\nUPSTREAM=' && (git rev-parse --abbrev-ref --symbolic-full-name '@{upstream}' 2>/dev/null || echo NONE)",
  "timeout": 30
}

{
  "command": "printf 'LOCAL_BRANCH_MATCHES\\n'; git for-each-ref --format='%(refname:short)|%(objectname)|%(worktreepath)' refs/heads | awk 'tolower($1) ~ /attack.*die|die.*attack/ || $1 == \"ideas/attack-die-3d\"'\nprintf 'REMOTE_TRACKING_MATCHES\\n'; git for-each-ref --format='%(refname:short)|%(objectname)' refs/remotes | awk 'tolower($1) ~ /attack.*die|die.*attack/ || $1 ~ /\\/ideas\\/attack-die-3d$/'\nprintf 'ORIGIN_MAIN_LOCAL_REF\\n'; if git show-ref --verify --quiet refs/remotes/origin/main; then git rev-parse refs/remotes/origin/main; else echo ABSENT; fi\nprintf 'LOCAL_MAIN_REF\\n'; if git show-ref --verify --quiet refs/heads/main; then git rev-parse refs/heads/main; else echo ABSENT; fi",
  "timeout": 30
}

{
  "command": "printf 'CANDIDATE_PATH='; candidate=/home/kirk/game-dev/rpg-project/.worktrees/attack-die-3d; if [ -e \"$candidate\" ] || [ -L \"$candidate\" ]; then echo PRESENT; else echo ABSENT; fi\nprintf 'CANDIDATE_REGISTERED='; if git worktree list --porcelain | grep -Fqx \"worktree $candidate\"; then echo YES; else echo NO; fi\nprintf 'EXACT_BRANCH_LOCAL='; if git show-ref --verify --quiet refs/heads/ideas/attack-die-3d; then echo PRESENT; else echo ABSENT; fi\nprintf 'EXACT_BRANCH_REMOTE='; if git show-ref --verify --quiet refs/remotes/origin/ideas/attack-die-3d; then echo PRESENT; else echo ABSENT; fi",
  "timeout": 30
}

{
  "command": "git status --porcelain=v2 --branch --untracked-files=all\nprintf 'COUNTS|'; git status --porcelain=v1 --untracked-files=all | awk 'substr($0,1,2)==\"??\"{u++;next}{t++; if(substr($0,1,1)!=\" \")s++; if(substr($0,2,1)!=\" \")w++} END{printf \"tracked=%d|untracked=%d|staged=%d|worktree_changes=%d\\n\",t+0,u+0,s+0,w+0}'",
  "timeout": 30
}

{
  "command": "printf 'SUBMODULE_ENTRIES='; git ls-files --stage | awk '$1==160000{n++} END{print n+0}'\nprintf 'SUPERPROJECT='; sp=$(git rev-parse --show-superproject-working-tree); if [ -n \"$sp\" ]; then printf '%s\\n' \"$sp\"; else echo NONE; fi\nprintf 'GITMODULES_TRACKED='; if git ls-files --error-unmatch .gitmodules >/dev/null 2>&1; then echo YES; else echo NO; fi",
  "timeout": 30
}
